import React,
{
useState,
useEffect
}
from "react";

import Navbar
from "../../components/Navbar";

import Sidebar
from "../../components/Sidebar";

import Loader
from "../../components/Loader";

import {
getAllUsers
}
from "../../api/userApi";

import {
getAllTransactions
}
from "../../api/bankingApi";

import {
getAllLoans
}
from "../../api/loanApi";

import {
getAllUserInvestments
}
from "../../api/investmentApi";

function Analytics(){

const [loading,setLoading]
=
useState(true);

const [users,setUsers]
=
useState([]);

const [transactions,
setTransactions]
=
useState([]);

const [loans,setLoans]
=
useState([]);

const [investments,
setInvestments]
=
useState([]);

useEffect(()=>{

loadData();

},[]);

const loadData =
async()=>{

try{

const usersRes =
await getAllUsers();

const transactionsRes =
await getAllTransactions();

const loansRes =
await getAllLoans();

const investmentsRes =
await getAllUserInvestments();

setUsers(usersRes.data||[]);
setTransactions(transactionsRes.data||[]);
setLoans(loansRes.data||[]);
setInvestments(investmentsRes.data||[]);

}
catch(error){

console.log(error);

}

setLoading(false);

};

if(loading){

return <Loader/>;

}

return(

<div>

<Navbar/>

<div className="d-flex">

<Sidebar/>

<div className="container-fluid p-4">

<div className="row">

<div className="col-md-3">

<div className="card">

<div className="card-body">

<h6>Total Users</h6>

<h2>{users.length}</h2>

</div>

</div>

</div>

<div className="col-md-3">

<div className="card">

<div className="card-body">

<h6>Total Transactions</h6>

<h2>{transactions.length}</h2>

</div>

</div>

</div>

<div className="col-md-3">

<div className="card">

<div className="card-body">

<h6>Total Loans</h6>

<h2>{loans.length}</h2>

</div>

</div>

</div>

<div className="col-md-3">

<div className="card">

<div className="card-body">

<h6>Total Investments</h6>

<h2>{investments.length}</h2>

</div>

</div>

</div>

</div>

<div className="card mt-4">

<div className="card-header">

System Overview

</div>

<div className="card-body">

<table className="table table-bordered">

<tbody>

<tr>
<td>Approved Loans</td>
<td>
{
loans.filter(
l=>l.status==="APPROVED"
).length
}
</td>
</tr>

<tr>
<td>Pending Loans</td>
<td>
{
loans.filter(
l=>l.status==="PENDING"
).length
}
</td>
</tr>

<tr>
<td>Rejected Loans</td>
<td>
{
loans.filter(
l=>l.status==="REJECTED"
).length
}
</td>
</tr>

<tr>
<td>Total Investors</td>
<td>
{
investments.length
}
</td>
</tr>

</tbody>

</table>

</div>

</div>

</div>

</div>

</div>

);

}

export default Analytics;
